<script setup>import {Head,Link} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import EmptyState from '../Components/EmptyState.vue';defineProps({managers:Array});const initials=n=>n.split(' ').map(x=>x[0]).join('').slice(0,2);</script><template><Head title="Managers"/><AppLayout><p class="label">The six</p><h1 class="mt-2 text-4xl font-black">Meet the managers.</h1><p class="mb-8 mt-2 text-[#718078]">Form, history and questionable decision-making.</p><div v-if="managers.length" class="grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><Link v-for="m in managers" :key="m.id" :href="`/managers/${m.id}`" class="card group p-6 hover:-translate-y-1 hover:border-[#85a795]"><div class="flex items-start justify-between"><span class="grid size-13 place-items-center rounded-2xl bg-[#163f2e] font-black text-[#f4d35e]">{{initials(m.manager_name)}}</span><span class="text-[#88958e]">↗</span></div><h2 class="mt-6 text-xl font-black group-hover:text-[#1d7650]">{{m.manager_name}}</h2><p class="text-sm text-[#718078]">{{m.team_name}}</p><div class="mt-6 flex justify-between border-t border-black/5 pt-4 dark:border-white/10"><span><small class="label block">Points</small><b>{{m.total_points}}</b></span><span class="text-right"><small class="label block">Overall</small><b>{{m.overall_rank?.toLocaleString()||'—'}}</b></span></div></Link></div><EmptyState v-else title="Manager profiles are waiting" text="All six profiles will be created from the league standings during the first sync."/></AppLayout></template>
